using System.Security.Cryptography;
using System.Text;
using System.Text.Encodings.Web;

namespace Markdown.Renderer;

// One publisher per site generation. Ordinary preview edits reuse the already published assets.
internal sealed class SiteAssets
{
    /// <summary>Output folder reserved for files generated by mdu, so they never collide with site assets.</summary>
    internal const string Folder = "_mdu";
    internal const string NavigationPath = Folder + "/js/navigation.js";
    internal const string SitemapPath = Folder + "/sitemap.html";

    internal static readonly string[] TemplateScripts =
    [
        "theme", "panels-init", "header-init", "navigation-controls", "tables",
        "panels", "scroll-navigation", "code-copy", "content-previews"
    ];

    private readonly string? _outputPath;
    // Site-relative path to content version; an empty version marks an asset without content.
    private readonly Dictionary<string, string> _versions;

    internal SiteAssets(string? outputPath) : this(outputPath, new Dictionary<string, string>(StringComparer.Ordinal)) { }

    private SiteAssets(string? outputPath, Dictionary<string, string> versions)
    {
        _outputPath = outputPath;
        _versions = versions;
    }

    /// <summary>
    /// Starts a new generation that keeps the published navigation, so pages rendered before the
    /// replacement navigation is ready (or after its preparation failed) stay consistent.
    /// </summary>
    internal SiteAssets ForNextGeneration() => new(_outputPath, _versions
        .Where(entry => entry.Key is NavigationPath or SitemapPath)
        .ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal));

    internal bool HasNavigation => _versions.ContainsKey(NavigationPath);

    /// <summary>Full paths of the asset files published in this generation.</summary>
    internal IEnumerable<string> PublishedPaths => _outputPath is null
        ? []
        : _versions.Where(entry => entry.Value.Length > 0).Select(entry => Path.Combine(_outputPath, entry.Key));

    /// <summary>The versioned site-relative URL of a published file.</summary>
    internal string Url(string relativePath) => relativePath + "?v=" + _versions[relativePath];

    internal string Script(string name, Func<string> content, string prefix)
    {
        if (_outputPath is null) return $"<script>{content()}</script>";
        var url = Publish(Folder + "/js/" + name + ".js", content);
        return url is null ? string.Empty : $"<script src=\"{HtmlEncoder.Default.Encode(prefix + url)}\"></script>";
    }

    internal string Styles(string name, Func<string> content, string prefix)
    {
        if (_outputPath is null)
        {
            var css = content();
            return css.Length == 0 ? string.Empty : $"<style>{css}</style>";
        }
        var url = Publish(Folder + "/css/" + name + ".css", content);
        return url is null ? string.Empty : $"<link rel=\"stylesheet\" href=\"{HtmlEncoder.Default.Encode(prefix + url)}\">";
    }

    /// <summary>Writes a file whose content changes within a generation, such as the navigation.</summary>
    internal void Replace(string relativePath, string content)
    {
        WriteAtomically(Path.Combine(_outputPath!, relativePath), content);
        _versions[relativePath] = Version(content);
    }

    // Returns the versioned site-relative URL, so a cached copy from an earlier deployment is never reused.
    private string? Publish(string relativePath, Func<string> content)
    {
        if (!_versions.TryGetValue(relativePath, out var version))
        {
            var text = content();
            version = text.Length == 0 ? string.Empty : Version(text);
            if (version.Length > 0) WriteAtomically(Path.Combine(_outputPath!, relativePath), text);
            _versions[relativePath] = version;
        }
        return version.Length == 0 ? null : relativePath + "?v=" + version;
    }

    internal static string Version(string content) =>
        Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(content)))[..12];

    internal static void WriteAtomically(string path, string content)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        var temporaryPath = path + "." + Guid.NewGuid().ToString("N") + ".tmp";
        try
        {
            File.WriteAllText(temporaryPath, content);
            File.Move(temporaryPath, path, overwrite: true);
        }
        finally
        {
            if (File.Exists(temporaryPath)) File.Delete(temporaryPath);
        }
    }
}
